\label{rephrasing-action}
We can summarise the action of $S_n$ on the set  $\mathcal{S} \sqcup \mathcal{S}^{-1}$ as
\begin{equation*}
\rho_i :
\begin{cases}
\lambda_{i, i+1} \longleftrightarrow \lambda_{i, i+1}^{-1}, & \\
\lambda_{i, j} \longleftrightarrow \lambda_{i+1, j} & \text{for all}\;\; i+2 \leq j \leq n,\\
\lambda_{j, i} \longleftrightarrow \lambda_{j, i+1} & \text{for all}\;\; 1\leq j < i,\\
\lambda_{k, l} \longleftrightarrow \lambda_{k, l} & \text{otherwise, i.e.,}\;\; k \geq i+2, \text{or}\;\; k < i \;\text{and}\; i\neq l \neq i+1.
\end{cases}
\end{equation*}
The action can be further simplified as
\begin{equation*}
\rho_i :
\begin{cases}
\lambda_{i, i+1} \longleftrightarrow \lambda_{i, i+1}^{-1}, & \\
\lambda_{k, l} \longleftrightarrow \lambda_{k', l'} & \text{for all}\;\; (k, l) \neq (i, i+1),
\end{cases}
\end{equation*} 
where the transposition $(k', l')$ equals $(i, i+1) (k, l) (i, i+1)$ and $k' < l'$. As seen in the proof of Theorem \ref{PVTn-generators}, the action of $S_n$ on the set $\mathcal{S} \sqcup \mathcal{S}^{-1}$ is transitive.

\label{pvtn-right-angled-artin}
The pure virtual twin group $PVT_n$ on  $n \ge 2 $ strands has the presentation
$$\big\langle \lambda_{i,j},~1 \leq i < j \leq n ~|~ \lambda_{i,j} \lambda_{k,l} =  \lambda_{k,l} \lambda_{i,j} \text{ for distinct integers } i, j, k, l \big\rangle.$$

\label{size-of-non-commuting-generators}
The following hold for each $\lambda_{i,j} \in \mathcal{S}$: 
\begin{enumerate}
\item $| N_{i,j} | = 2n - 4$.
\item $| st(\lambda_{i,j})| = \dfrac{(n-2)(n-4)+n}{2}$. In particular, the graph of $PVT_n$ is  regular. 
\end{enumerate}

\label{aut-pvtn-main}
Let $n \ge 5$. Then there exist split exact sequences 
\begin{equation}\label{auto-seq-1}
1\rightarrow \operatorname{Aut}_{inv}(PVT_n)\rightarrow   \langle \operatorname{Aut}_{gr}(PVT_n), \operatorname{Aut}_{inv}(PVT_n) \rangle \rightarrow \operatorname{Aut}_{gr}(PVT_n) \to 1
\end{equation}
and 
\begin{equation}\label{auto-seq-2}
1\rightarrow \operatorname{Inn}(PVT_n)\rightarrow \operatorname{Aut}(PVT_n)\rightarrow  \langle \operatorname{Aut}_{gr}(PVT_n), \operatorname{Aut}_{inv}(PVT_n) \rangle \to 1.
\end{equation}
In particular,
$$\langle \operatorname{Aut}_{gr}(PVT_n), \operatorname{Aut}_{inv}(PVT_n) \rangle \cong \mathbb{Z}_2^{n(n-1)/2} \rtimes S_n$$
and 
$$\operatorname{Aut}(PVT_n) \cong PVT_n \rtimes (\mathbb{Z}_2^{n(n-1)/2} \rtimes S_n).$$

\label{graph-inv-tr-structure}
$$\operatorname{Aut}_{gr}(PVT_4) \cap \langle \operatorname{Aut}_{inv}(PVT_4), \operatorname{Aut}_{tr}(PVT_4) \rangle = \langle \sigma_1, \sigma_2, \sigma_3 \rangle \cong \mathbb{Z}_2 \times \mathbb{Z}_2 \times \mathbb{Z}_2$$
and
\begin{align*}
\langle \operatorname{Aut}_{gr}(PVT_4), \operatorname{Aut}_{inv}(PVT_4), \operatorname{Aut}_{tr}(PVT_4) \rangle &= \langle \operatorname{Aut}_{inv}(PVT_4), \operatorname{Aut}_{tr}(PVT_4) \rangle \rtimes \langle \psi_1, \psi_2 \rangle &\\
& \cong \big ( \operatorname{GL}_2 (\mathbb{Z}) \times \operatorname{GL}_2 (\mathbb{Z}) \times \operatorname{GL}_2 (\mathbb{Z}) \big )\rtimes S_3.&
\end{align*}

\label{relations in Aut_pc(PVT_4)}
The group $\operatorname{Aut}_{pc}(PVT_4)$ has a presentation with generating set $$\{p_{x_i, C_j}, p_{y_i, C_j}~|~ i \neq j \text{ and } i, j =1, 2, 3\}$$ and following defining relations: 

\begin{enumerate}
\item $[p_{x_i, C_j},\; p_{x_i, C_k}] =[p_{y_i, C_j},\; p_{y_i, C_k}]= [p_{x_i, C_j},\; p_{y_i, C_k}] = [p_{x_i, C_j},\; p_{y_i, C_j}] =1$ for $i = 1, 2, 3$ with $i \neq j \neq k \neq i$.
\item $[p_{x_i, C_j} p_{x_i, C_k},\; p_{x_j, C_k}] = [p_{y_i, C_j} p_{y_i, C_k},\; p_{y_j, C_k}] = [p_{x_i, C_j} p_{x_i, C_k},\; p_{y_j, C_k}] = [p_{y_i, C_j} p_{y_i, C_k},\; p_{x_j, C_k}] =1$~~ for $i, j, k = 1, 2, 3$ with $i \neq j \neq k \neq i$.
\end{enumerate}
In particular, $$\operatorname{Aut}_{pc}(PVT_4) \cong (\mathbb{Z}^2 \ast \mathbb{Z}^2 \ast \mathbb{Z}^2) \rtimes (\mathbb{Z}^2 \ast \mathbb{Z}^2 \ast \mathbb{Z}^2). $$

\label{splitting-auto-pvt4}
There exists a split exact sequence
$$1 \to  \operatorname{Aut}_{pc}(PVT_4) \to \operatorname{Aut}(PVT_4)  \to  \big\langle \operatorname{Aut}_{gr}(PVT_4), \operatorname{Aut}_{inv}(PVT_4), \operatorname{Aut}_{tr}(PVT_4)  \big\rangle \to 1.$$
In particular, 
\begin{align*}
\operatorname{Aut}(PVT_4) & = \operatorname{Aut}_{pc}(PVT_4) \rtimes \big\langle \operatorname{Aut}_{gr}(PVT_4), \operatorname{Aut}_{inv}(PVT_4), \operatorname{Aut}_{tr}(PVT_4)  \big\rangle&\\
&\cong ((\mathbb{Z}^2 \ast \mathbb{Z}^2 \ast \mathbb{Z}^2) \rtimes (\mathbb{Z}^2 \ast \mathbb{Z}^2 \ast \mathbb{Z}^2)) \rtimes \big ( (\operatorname{GL}_2 (\mathbb{Z}) \times \operatorname{GL}_2 (\mathbb{Z}) \times \operatorname{GL}_2 (\mathbb{Z})) \rtimes S_3 \big ).&
\end{align*}
